void bfs(int start, const Graph& g) {
    std::vector<int> dist(g.V, -1);
    std::queue<int> q;
    dist[start] = 0;
    q.push(start);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        visit(u);
        for (const auto& e : g.adj[u]) {
            int v = e.to;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.push(v);
            }
        }
    }
}

