void primsMST(int start, const Graph& g) {
    std::vector<int> key(g.V, INF);
    std::vector<bool> inMST(g.V, false);
    std::priority_queue<Edge, vector<Edge>, greater<Edge>> pq;
    key[start] = 0;
    pq.push({0, -1, start});
    while (!pq.empty()) {
        auto [w, u, v] = pq.top(); pq.pop();
        if (inMST[v]) continue; // skip cycle/stale
        inMST[v] = true;
        if (u != -1) addEdgeToMST(u, v, w);
        for (const auto& e : g.adj[v]) {
            if (!inMST[e.to] && e.weight < key[e.to]) {
                key[e.to] = e.weight;
                parent[e.to] = v;
                pq.push({e.weight, v, e.to});
            }
        }
    }
}

