void kruskalsMST(int V, vector<Edge>& edges) {
    sort(edges.begin(), edges.end());
    DSU dsu(V);
    int totalWeight = 0, mstEdges = 0;
    for (const auto& e : edges) {
        int rootU = dsu.find(e.u);
        int rootV = dsu.find(e.v);
        if (rootU != rootV) {
            dsu.unite(rootU, rootV);
            totalWeight += e.w;
            mstEdges++;
            addMstEdge(e);
            if (mstEdges == V - 1) break;
        } // else: cycle detected -> discard
    }
}

